/**
 * Regenerates `src/db/seed/data/banks.ts` from the public VietQR bank list
 * (https://api.vietqr.io/v2/banks). Run with `npm run seed:fetch-banks`.
 *
 * The seed itself reads the generated file, so `npm run seed` works offline and
 * produces the same result every time; only run this script to refresh the list.
 */
import { mkdirSync, writeFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

interface VietQrBank {
  code: string
  name: string
  shortName: string
}

const API_URL = 'https://api.vietqr.io/v2/banks'
const OUT_FILE = resolve(
  dirname(fileURLToPath(import.meta.url)),
  'data/banks.ts',
)

const res = await fetch(API_URL)
if (!res.ok) throw new Error(`VietQR API returned HTTP ${res.status}`)
const json = (await res.json()) as { code: string; data?: VietQrBank[] }
if (json.code !== '00' || !json.data?.length)
  throw new Error(
    `Unexpected VietQR response: ${JSON.stringify(json).slice(0, 200)}`,
  )

// Keep only what the `banks` table stores; sort for stable diffs
const banks = json.data
  .map((b) => ({
    code: b.code.trim(),
    name: b.name.trim(),
    shortName: b.shortName.trim(),
  }))
  .sort((a, b) => a.shortName.localeCompare(b.shortName, 'vi'))

const codes = new Set(banks.map((b) => b.code))
if (codes.size !== banks.length)
  throw new Error('Duplicate bank codes in API data')

const body = banks
  .map(
    (b) =>
      `  { code: ${JSON.stringify(b.code)}, name: ${JSON.stringify(b.name)}, shortName: ${JSON.stringify(b.shortName)} },`,
  )
  .join('\n')

mkdirSync(dirname(OUT_FILE), { recursive: true })
writeFileSync(
  OUT_FILE,
  `/**
 * GENERATED by \`npm run seed:fetch-banks\` from ${API_URL}
 * (${banks.length} banks, fetched ${new Date().toISOString().slice(0, 10)}). Do not edit by hand.
 */
export const VIETNAM_BANKS: { code: string; name: string; shortName: string }[] = [
${body}
]
`,
)
console.log(`Wrote ${banks.length} banks to ${OUT_FILE}`)
